export const getListPrescriptionsUrl = (clinicId: string,
    params?: ListPrescriptionsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/clinics/${clinicId}/prescriptions?${stringifiedParams}` : `/api/clinics/${clinicId}/prescriptions`
}

