export const getGetFinanceSummaryUrl = (clinicId: string,
    params?: GetFinanceSummaryParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/clinics/${clinicId}/finances/summary?${stringifiedParams}` : `/api/clinics/${clinicId}/finances/summary`
}

